import{_ as r,o as e,c as t,ag as o}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"天人合一","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-天人合一.md","filePath":"10-核心模型/model-天人合一.md","lastUpdated":1778031108000}'),l={name:"10-核心模型/model-天人合一.md"};function n(i,a,s,h,d,p){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="天人合一" tabindex="-1">天人合一 <a class="header-anchor" href="#天人合一" aria-label="Permalink to &quot;天人合一&quot;">​</a></h1><blockquote><p>了空居士智慧体系的基础世界观。 一切不永恒但因果不虚，道无处不在，人与宇宙是能量一体。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>天人合一</strong> 是了空居士整个teaching的起点。它不是一种抽象的哲学概念，而是可以通过实修体验到的生命实相——<strong>人与宇宙能量场是一个整体</strong>。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-缘起性空" tabindex="-1">1. 缘起性空 <a class="header-anchor" href="#_1-缘起性空" aria-label="Permalink to &quot;1. 缘起性空&quot;">​</a></h3><p><strong>原文</strong>：佛说非身，是名大身。若见诸相非相，即见如来。</p><p><strong>解读</strong>：一切现象都是因缘和合而生，没有永恒不变的本质。这不是消极的空无，而是告诉我们——不永恒的，是可以改变的；不永恒的，是不必执着的。</p><h3 id="_2-万法一体" tabindex="-1">2. 万法一体 <a class="header-anchor" href="#_2-万法一体" aria-label="Permalink to &quot;2. 万法一体&quot;">​</a></h3><p><strong>原文</strong>：一滴水与大海融为一体。到底是大海得到一滴水，还是一滴水得到了大海？</p><p><strong>解读</strong>：我与世界不是对立的关系，而是互融互摄的关系。就像水滴投入大海，分不清谁得到了谁，这就是一体。</p><h3 id="_3-因果不空" tabindex="-1">3. 因果不空 <a class="header-anchor" href="#_3-因果不空" aria-label="Permalink to &quot;3. 因果不空&quot;">​</a></h3><p><strong>原文</strong>：万法皆空，因果不空。</p><p><strong>解读</strong>：万事万物都不是永恒的（万法皆空），但是因果相续的规律是永恒的（因果不空）。过去的因＋现在的缘＝未来的果，这个规律不会改变。</p><h3 id="_4-观天之道-执天之行" tabindex="-1">4. 观天之道，执天之行 <a class="header-anchor" href="#_4-观天之道-执天之行" aria-label="Permalink to &quot;4. 观天之道，执天之行&quot;">​</a></h3><p><strong>原文</strong>：观察大自然的规律，并以此规范我们的行为。</p><p><strong>解读</strong>：道在天地万物中。观天之道就是观察自然规律，执天之行就是按规律去做人做事。</p><h3 id="_5-天性人也" tabindex="-1">5. 天性人也 <a class="header-anchor" href="#_5-天性人也" aria-label="Permalink to &quot;5. 天性人也&quot;">​</a></h3><p><strong>原文</strong>：真正的标准的人要与天地一样的性质。</p><p><strong>解读</strong>：人的本质与天（自然）是一致的。天的性质是大公无私、平等对待万物，人的本性也应当如此。</p><h3 id="_6-能量共振" tabindex="-1">6. 能量共振 <a class="header-anchor" href="#_6-能量共振" aria-label="Permalink to &quot;6. 能量共振&quot;">​</a></h3><p><strong>原文</strong>：宇宙的能量场有无穷无尽的频道，我们通过修行慢慢与更多的场同步共振。</p><p><strong>解读</strong>：人体本身就是一个能量场，宇宙也是能量场。修行就是调整自身的频率，与越来越多层次的宇宙能量场共振。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>在日常生活中</strong>：</p><ul><li>遇到不顺心的事，问自己：这件事的因果链条是什么？</li><li>用&quot;观天之道&quot;的心态——观察规律、按规律行事，不逆天而行</li><li>感受自己与周围环境的一体性，我即是环境的一部分</li></ul><p><strong>在修行中</strong>：</p><ul><li>静坐时体会身体的虚无感与体外的能量场</li><li>不着意追求境界，缘起性空自然呈现</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 天人合一的心态体现</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 天人合一的功法实践</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第10分（庄严净土分）</li><li>道德经讲解</li><li>虚无中的共振：天人合一的能量实相</li><li>中论丹道</li><li>五篇灵文</li></ul><blockquote><p>来源：<a href="/10了空居士讲《金刚经》-第十分庄严净土分20161104">10了空居士讲《金刚经》-第十分庄严净土分20161104</a>、<a href="/道德经讲解">道德经讲解</a>、<a href="/20090111a虚无中的共振">20090111a虚无中的共振</a>、<a href="/中论丹道_了空居士_完整版(全83篇)">中论丹道_了空居士_完整版(全83篇)</a> 蒸馏日期：2026-05-05</p></blockquote>',37)])])}const _=r(l,[["render",n]]);export{c as __pageData,_ as default};
